Meadow.source:
const widgetTheme = {
  "titleFont": "headline",
  "bodyFont": "caption",
  "fontDesign": "rounded",
  "corner": 20,
  "padding": 16,
  "spacing": 10,
  "background": "#F2FAF5",
  "surface": "#FFFFFF",
  "foreground": "#193F31",
  "muted": "#607C70",
  "accent": "#328963"
};
// Keep my code
const day='Monday';
$render(
  <vstack spacing={widgetTheme.spacing} alignment="leading" padding={widgetTheme.padding} background={widgetTheme.background} corner={widgetTheme.corner}>
    <text font={widgetTheme.bodyFont} color={widgetTheme.muted} fontDesign={widgetTheme.fontDesign}>A fresh start</text>
    <text font={widgetTheme.titleFont} color={widgetTheme.foreground} fontDesign={widgetTheme.fontDesign}>Calm morning</text>
    <text font={widgetTheme.bodyFont} color={widgetTheme.muted} fontDesign={widgetTheme.fontDesign}>{day}</text>
  </vstack>
);

